import React, { useState } from "react";
import "../styles/roadmap.css";

function LegalRoadmapGenerator() {

  const [caseType, setCaseType] = useState("");
  const [steps, setSteps] = useState([]);

  const generateRoadmap = () => {

    let roadmap = [];

    if (caseType === "Criminal") {
      roadmap = [
        "File FIR",
        "Police Investigation",
        "Court Hearing",
        "Evidence Submission",
        "Final Judgment"
      ];
    }

    if (caseType === "Family") {
      roadmap = [
        "Consult Lawyer",
        "File Petition",
        "Mediation",
        "Court Hearing",
        "Final Decision"
      ];
    }

    if (caseType === "Property") {
      roadmap = [
        "Document Verification",
        "Legal Notice",
        "Court Case Filing",
        "Evidence Review",
        "Court Decision"
      ];
    }

    setSteps(roadmap);
  };

  return (
    <div className="roadmap-container">

      <h1>Legal Roadmap Generator</h1>

      <div className="roadmap-form">

        <label>Select Case Type</label>

        <select
          value={caseType}
          onChange={(e) => setCaseType(e.target.value)}
        >
          <option value="">-- Select Case --</option>
          <option value="Criminal">Criminal Case</option>
          <option value="Family">Family Case</option>
          <option value="Property">Property Case</option>
        </select>

        <button onClick={generateRoadmap}>
          Generate Roadmap
        </button>

        <ul className="steps-list">
          {steps.map((step, index) => (
            <li key={index}>{step}</li>
          ))}
        </ul>

      </div>

    </div>
  );
}

export default LegalRoadmapGenerator;
